using System;
using System.Text;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class AssignStoneGateOpenSound
{
    public static string Run()
    {
        if (EditorApplication.isPlaying || EditorUtility.scriptCompilationFailed)
            throw new InvalidOperationException("Compiled Edit Mode required.");
        const string path = "Assets/Audio/SFX/Imported/StoneGateOpen.mp3";
        var importer = (AudioImporter)AssetImporter.GetAtPath(path);
        var settings = importer.defaultSampleSettings;
        settings.loadType = AudioClipLoadType.DecompressOnLoad;
        settings.compressionFormat = AudioCompressionFormat.PCM;
        settings.preloadAudioData = true;
        importer.defaultSampleSettings = settings;
        importer.SaveAndReimport();
        var clip = AssetDatabase.LoadAssetAtPath<AudioClip>(path);
        if (clip == null || clip.length <= 0f) throw new Exception("Invalid open sound clip.");
        const string prefabPath = "Assets/Prefabs/Gimmicks/GimmickDoor.prefab";
        var root = PrefabUtility.LoadPrefabContents(prefabPath);
        try
        {
            var so = new SerializedObject(root.GetComponent<GimmickDoor>());
            so.FindProperty("openClip").objectReferenceValue = clip;
            so.FindProperty("openVolume").floatValue = 0.9f;
            so.ApplyModifiedPropertiesWithoutUndo();
            PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
        }
        finally { PrefabUtility.UnloadPrefabContents(root); }
        var report = new StringBuilder();
        report.AppendLine("Assigned supplied clip: " + clip.name + " length=" + clip.length + " volume=0.9");
        foreach (var door in UnityEngine.Object.FindObjectsByType<GimmickDoor>(FindObjectsInactive.Include))
        {
            var so = new SerializedObject(door);
            if (so.FindProperty("openClip").objectReferenceValue != clip)
                throw new Exception("Open scene did not inherit sound: " + door.name);
            report.AppendLine("Open scene inherited clip: " + door.gameObject.scene.name + "/" + door.name);
        }
        foreach (var scenePath in new[]{"Assets/Scenes/Stage1.unity", "Assets/Scenes/CompletScene.unity"})
        {
            var preview = EditorSceneManager.OpenPreviewScene(scenePath);
            try
            {
                int count=0;
                foreach(var r in preview.GetRootGameObjects())
                    foreach(var door in r.GetComponentsInChildren<GimmickDoor>(true))
                    {
                        var so = new SerializedObject(door);
                        if (so.FindProperty("openClip").objectReferenceValue != clip)
                            throw new Exception("Saved scene did not inherit clip: " + scenePath);
                        count++;
                    }
                report.AppendLine(scenePath + " sound inheritance verified: " + count + " door(s)");
            }
            finally { EditorSceneManager.ClosePreviewScene(preview); }
        }
        report.AppendLine("compileFailed=" + EditorUtility.scriptCompilationFailed);
        return report.ToString();
    }
}
